import { buildDeepLink } from "@agent-native/core/server";
import { defineAction, fail } from "@agent-native/core/action";
import { and, eq } from "drizzle-orm";
import { z } from "zod";
import { getDb } from "../server/db/index.js";
import { tasks } from "../server/db/schema.js";
import { getOwnedTask, requireTaskOwner } from "../server/db/task-store.js";

export default defineAction({
  description: "Complete the authenticated user's private task by id. Idempotent: already-completed tasks stay completed.",
  link: ({ result }: { result: unknown }) => {
    const task = z.object({ id: z.string(), title: z.string() }).parse(result);
    return { url: buildDeepLink({ app: "pristine", view: "tasks", to: `/tasks?id=${encodeURIComponent(task.id)}` }), label: task.title };
  },
  schema: z.object({ id: z.string().uuid().describe("ID of the task to complete") }).strict(),
  run: async ({ id }, context) => {
    const ownerEmail = requireTaskOwner(context);
    const rows = await getDb().update(tasks).set({ completed: true })
      .where(and(eq(tasks.id, id), eq(tasks.ownerEmail, ownerEmail))).returning({ id: tasks.id });
    if (!rows.length) fail("Tarefa não encontrada.", { statusCode: 404, errorCode: "not_found" });
    return getOwnedTask(id, ownerEmail);
  },
});

import { buildDeepLink } from "@agent-native/core/server";
import { randomUUID } from "node:crypto";
import { defineAction } from "@agent-native/core/action";
import { z } from "zod";
import { getDb } from "../server/db/index.js";
import { tasks } from "../server/db/schema.js";
import { getOwnedTask, requireTaskOwner } from "../server/db/task-store.js";

export default defineAction({
  description: "Create a private task for the authenticated user. Returns its id and title; use navigate view=tasks id=<id> to open it.",
  link: ({ result }: { result: unknown }) => {
    const task = z.object({ id: z.string(), title: z.string() }).parse(result);
    return { url: buildDeepLink({ app: "pristine", view: "tasks", to: `/tasks?id=${encodeURIComponent(task.id)}` }), label: task.title };
  },
  schema: z.object({ title: z.string().trim().min(1).max(200).describe("Task title, 1 to 200 characters after trimming") }).strict(),
  run: async ({ title }, context) => {
    const ownerEmail = requireTaskOwner(context);
    const id = randomUUID();
    await getDb().insert(tasks).values({ id, title, ownerEmail, createdAt: new Date().toISOString() });
    return getOwnedTask(id, ownerEmail);
  },
});

