import { defineAction, fail } from "@agent-native/core/action";
import { writeAppStateForCurrentTab } from "@agent-native/core/application-state";
import { getOwnedTask, requireTaskOwner } from "../server/db/task-store.js";
import { z } from "zod";

export default defineAction({
  description:
    "Navigate the UI to a specific view or path. Writes a navigate command to application state which the UI reads and auto-deletes.",
  schema: z.object({
    view: z.string().optional().describe("View name to navigate to"),
    path: z.string().optional().describe("URL path to navigate to"),
    id: z.string().uuid().optional().describe("Private task ID to open in the tasks view"),
    threadId: z.string().optional().describe("Chat thread ID to open"),
  }),
  http: false,
  run: async (args, context) => {
    const owner = requireTaskOwner(context);
    if (args.id) await getOwnedTask(args.id, owner);
    const destination = args.path ? new URL(args.path, "http://local") : null;
    if (destination && (!args.path?.startsWith("/") || args.path.startsWith("//") || destination.origin !== "http://local")) fail("Use um caminho local do aplicativo.", { errorCode: "invalid_path" });
    if (destination?.pathname === "/tasks" && destination.searchParams.has("id")) {
      await getOwnedTask(z.string().uuid().parse(destination.searchParams.get("id")), owner);
    }
    if (!args.view && !args.path) {
      fail("Informe uma tela ou caminho.", { errorCode: "invalid_navigation" });
    }
    const nav: Record<string, string> = {};
    if (args.view) nav.view = args.view;
    if (args.path) nav.path = args.path;
    if (args.view === "tasks" || args.id) {
      nav.view = "tasks";
      nav.path = args.id ? `/tasks?id=${encodeURIComponent(args.id)}` : args.path ?? "/tasks";
    }
    if (args.threadId) nav.threadId = args.threadId;
    nav._writeId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    await writeAppStateForCurrentTab("navigate", nav);
    return `Navigating to ${args.view || args.path}`;
  },
});

import { defineAction } from "@agent-native/core/action";
import { readAppStateForCurrentTab } from "@agent-native/core/application-state";
import { z } from "zod";
import { getOwnedTask, listOwnedTasks, requireTaskOwner } from "../server/db/task-store.js";

const navigationSchema = z.object({ view: z.string(), taskId: z.string().uuid().optional() }).passthrough();
const selectionSchema = z.object({ kind: z.literal("task"), id: z.string().uuid() });

export default defineAction({
  description: "Read fresh authorized screen details, including the private task list, opened task, and current task selection.",
  schema: z.object({}),
  http: false,
  readOnly: true,
  run: async (_args, context) => {
    const owner = requireTaskOwner(context);
    const navigation = await readAppStateForCurrentTab("navigation");
    const parsed = navigationSchema.safeParse(navigation);
    const screen: Record<string, unknown> = { navigation };
    if (parsed.success && parsed.data.view === "tasks") {
      screen.tasks = await listOwnedTasks(owner);
      if (parsed.data.taskId) screen.openedTask = await getOwnedTask(parsed.data.taskId, owner);
      const selection = selectionSchema.safeParse(await readAppStateForCurrentTab("selection"));
      if (selection.success && selection.data.id === parsed.data.taskId) {
        await getOwnedTask(selection.data.id, owner);
        screen.selection = selection.data;
      }
    }
    return screen;
  },
});

import { useT } from "@agent-native/core/client/i18n";
import {
  navigateWithAgentChatViewTransition,
  useAgentChatRunningThreads,
  useChatThreads,
  type ChatThreadSummary,
} from "@agent-native/toolkit/app/chat/agentkit-chat/rail";
import { ReportProblemButton } from "@agent-native/toolkit/app/feedback";
import { OrgSwitcher } from "@agent-native/toolkit/app/org";
import { openCommandMenu } from "@agent-native/toolkit/app/shared";
import { AgentNativeIcon } from "@agent-native/toolkit/app/shared/AgentNativeIcon";
import {
  ChatHistoryList,
  type ChatHistoryItem,
  type ChatHistorySection,
} from "@agent-native/toolkit/chat-history/ChatHistoryList";
import {
  IconApps,
  IconClock,
  IconEdit,
  IconHome,
  IconLayoutSidebarLeftCollapse,
  IconLayoutSidebarLeftExpand,
  IconLoader2,
  IconMessages,
  IconPin,
  IconSearch,
} from "@tabler/icons-react";
