import { useEffect, useRef } from "react";
import { useLocation } from "react-router";
import { deleteClientAppState, writeClientAppState } from "@agent-native/core/client/hooks";
import { appBasePath, appPath } from "@agent-native/core/client/api-path";
import { useAgentRouteState } from "@agent-native/core/client/navigation";

import {
  chatThreadPath,
  HOME_PATH,
  isChatPathname,
  NEW_CHAT_PATH,
  threadIdFromPath,
} from "@/lib/chat-paths";
import { TAB_ID } from "@/lib/tab-id";

export interface NavigationState {
  view: string;
  path?: string;
  threadId?: string;
  taskId?: string;
}

export function useNavigationState() {
  const location = useLocation();
  const stateWrites = useRef(Promise.resolve());
  const selectedTaskId = location.pathname === "/tasks" ? new URLSearchParams(location.search).get("id") : null;
  useEffect(() => {
    stateWrites.current = stateWrites.current.catch(() => {}).then(async () => {
      const options = { requestSource: TAB_ID };
      if (selectedTaskId) await writeClientAppState(`selection:${TAB_ID}`, { kind: "task", id: selectedTaskId }, options);
      else await deleteClientAppState(`selection:${TAB_ID}`, options);
    });
  }, [location.pathname, selectedTaskId]);
  useAgentRouteState<NavigationState>({
    navigateOptions: { replace: true, flushSync: true },
    agentChatViewTransition: false,
    browserTabId: TAB_ID,
    requestSource: TAB_ID,
    getNavigationState: ({ pathname, searchParams }) => {
      const threadId = threadIdFromPath(pathname);
      return {
        view: viewForPath(pathname),
        path: appPath(pathname),
        ...(threadId ? { threadId } : {}),
        ...(pathname === "/tasks" && searchParams.get("id") ? { taskId: searchParams.get("id")! } : {}),
      };
    },
    getCommandPath: (command) =>
      routerPath(command.path || pathForCommand(command)),
  });
}

function viewForPath(pathname: string): string {
  if (pathname === "/tasks") return "tasks";
  if (isChatPathname(pathname)) return "chat";
  if (pathname === HOME_PATH) return "home";
  if (pathname.startsWith("/database")) return "database";
  if (pathname.startsWith("/extensions")) return "extensions";
  if (pathname.startsWith("/observability")) return "observability";
  if (pathname.startsWith("/settings/agent") || pathname.startsWith("/agent")) {
    return "agent";
  }
  if (pathname.startsWith("/settings")) return "settings";
  if (pathname.startsWith("/team")) return "settings";
  return "chat";
}

function pathForView(view?: string): string {
  switch (view) {
    case "chat":
    case "ask":
      return NEW_CHAT_PATH;
    case "home":
      return HOME_PATH;
    case "tasks":
      return "/tasks";
    case "database":
      return "/database";
    case "extensions":
      return "/extensions";
    case "observability":
      return "/observability";
    case "agent":
      return "/settings/agent";
    case "settings":
      return "/settings";
    case "team":
      return "/settings/organization";
    default:
      return HOME_PATH;
  }
}

export function pathForCommand(command: NavigationState): string {
  const path = pathForView(command?.view);
  if (command?.view !== "chat" && command?.view !== "ask") return path;
  const threadId =
    typeof command?.threadId === "string" ? command.threadId.trim() : "";
  return threadId ? chatThreadPath(threadId) : path;
}

function routerPath(path: string): string {
  const basePath = appBasePath();
  if (!basePath) return path;
  if (path === basePath) return "/";
  if (path.startsWith(`${basePath}/`)) {
    return path.slice(basePath.length) || "/";
  }
  return path;
}

import { useT } from "@agent-native/core/client/i18n";
import { actionErrorMessage, useActionMutation, useActionQuery, useDbSync } from "@agent-native/core/client/hooks";
import { useQueryClient } from "@tanstack/react-query";
import { useEffect, useRef, useState, type FormEvent } from "react";
import { Link, useSearchParams } from "react-router";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { TAB_ID } from "@/lib/tab-id";

export default function TasksPage() {
  const t = useT();
  const queryClient = useQueryClient();
  useDbSync({ queryClient, ignoreSource: TAB_ID, realtime: { reason: "The same owner's second authenticated session must see task changes before refresh" }, pauseWhenHidden: true });
  const tasks = useActionQuery("list-tasks", {});
  const create = useActionMutation("create-task");
  const complete = useActionMutation("complete-task");
  const [searchParams, setSearchParams] = useSearchParams();
  const openedId = searchParams.get("id");
  const openedTask = tasks.data?.find((task) => task.id === openedId);
  const [title, setTitle] = useState("");
  const [notice, setNotice] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const detailRef = useRef<HTMLHeadingElement>(null);
  useEffect(() => { if (openedId) detailRef.current?.focus(); }, [openedId, openedTask?.id]);

  async function createTask(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setNotice("");
    try {
      const task = await create.mutateAsync({ title: title.trim() });
      setTitle("");
      setNotice(t("tasks.created"));
      setSearchParams({ id: task.id });
    } catch { inputRef.current?.focus(); }
  }

  async function completeTask(id: string) {
    setNotice("");
    try {
      await complete.mutateAsync({ id });
      setNotice(t("tasks.completedNotice"));
    } catch { /* The action error is rendered below. */ }
  }

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 overflow-y-auto p-4 sm:p-8">
      <h1 className="text-2xl font-semibold">{t("tasks.title")}</h1>
      <form onSubmit={createTask} className="flex flex-col gap-2 sm:flex-row sm:items-end">
        <div className="min-w-0 flex-1">
          <label htmlFor="task-title" className="mb-2 block text-sm font-medium">{t("tasks.titleLabel")}</label>
          <Input ref={inputRef} id="task-title" value={title} onChange={(event) => setTitle(event.target.value)} maxLength={200} aria-invalid={Boolean(create.error)} aria-describedby={create.error ? "task-write-error" : undefined} required disabled={create.isPending} />
        </div>
        <Button type="submit" disabled={create.isPending || !title.trim()}>{create.isPending ? t("tasks.creating") : t("tasks.create")}</Button>
      </form>
      <p role="status" aria-live="polite">{notice}</p>
      {create.error || complete.error ? <p id="task-write-error" role="alert" className="text-destructive">{actionErrorMessage(create.error ?? complete.error) ?? t("tasks.saveError")}</p> : null}
      {tasks.isPending ? <p role="status">{t("tasks.loading")}</p> : tasks.isError ? (
        <div role="alert"><p>{actionErrorMessage(tasks.error) ?? t("tasks.loadError")}</p><Button onClick={() => void tasks.refetch()}>{t("tasks.retry")}</Button></div>
      ) : tasks.data?.length === 0 ? <p>{t("tasks.empty")}</p> : (
        <ul aria-label={t("tasks.title")} className="space-y-2">
          {tasks.data?.map((task) => <li key={task.id} className="flex flex-wrap items-center gap-3 rounded-lg border p-3">
            <Link to={`/tasks?id=${encodeURIComponent(task.id)}`} aria-current={openedId === task.id ? "true" : undefined} className="min-w-0 flex-1 break-words rounded focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{task.title}</Link>
            <span className="text-sm text-muted-foreground">{task.completed ? t("tasks.completed") : t("tasks.pending")}</span>
            {!task.completed ? <Button variant="outline" disabled={complete.isPending} onClick={() => void completeTask(task.id)} aria-label={`${t("tasks.complete")} ${task.title}`}>{complete.isPending && complete.variables?.id === task.id ? t("tasks.completing") : t("tasks.complete")}</Button> : null}
          </li>)}
        </ul>
      )}
      {openedId && !tasks.isPending && !tasks.isError ? <section className="rounded-lg border p-4" aria-label={t("tasks.opened")}>
        <h2 tabIndex={-1} ref={detailRef} className="break-words text-lg font-semibold focus-visible:ring-2 focus-visible:ring-ring">{openedTask?.title ?? t("tasks.missing")}</h2>
        {openedTask ? <p>{openedTask.completed ? t("tasks.completed") : t("tasks.pending")}</p> : null}
        <Button variant="outline" className="mt-3" onClick={() => { setSearchParams({}); inputRef.current?.focus(); }}>{t("tasks.close")}</Button>
      </section> : null}
    </main>
  );
}

import { createGetDb } from "@agent-native/core/db";
import * as schema from "./schema.js";

export const getDb = createGetDb(schema);

import { boolean, index, pgTable, text } from "drizzle-orm/pg-core";

export const tasks = pgTable("tasks", {
  id: text("id").primaryKey(),
  title: text("title").notNull(),
  completed: boolean("completed").notNull().default(false),
  ownerEmail: text("owner_email").notNull(),
  createdAt: text("created_at").notNull(),
}, (table) => [index("tasks_owner_created_idx").on(table.ownerEmail, table.createdAt)]);

import { fail, type ActionRunContext } from "@agent-native/core/action";
import { and, desc, eq } from "drizzle-orm";
import { getDb } from "./index.js";
import { tasks } from "./schema.js";

export function requireTaskOwner(context?: ActionRunContext): string {
  const email = context?.userEmail?.trim().toLowerCase();
  if (!email) fail("Entre para acessar suas tarefas.", { statusCode: 401, errorCode: "unauthenticated" });
  return email;
}

export async function listOwnedTasks(ownerEmail: string) {
  return getDb().select({ id: tasks.id, title: tasks.title, completed: tasks.completed, createdAt: tasks.createdAt })
    .from(tasks).where(eq(tasks.ownerEmail, ownerEmail)).orderBy(desc(tasks.createdAt), tasks.id);
}

export async function getOwnedTask(id: string, ownerEmail: string) {
  const [task] = await getDb().select({ id: tasks.id, title: tasks.title, completed: tasks.completed, createdAt: tasks.createdAt })
    .from(tasks).where(and(eq(tasks.id, id), eq(tasks.ownerEmail, ownerEmail))).limit(1);
  if (!task) fail("Tarefa não encontrada.", { statusCode: 404, errorCode: "not_found" });
  return task;
}

