import listTasks from "../actions/list-tasks.js";
import completeTask from "../actions/complete-task.js";
import * as schema from "../server/db/schema.js";

const owner: ActionRunContext = { userEmail: "owner@example.test", caller: "frontend" };
const other: ActionRunContext = { userEmail: "other@example.test", caller: "tool" };

beforeAll(async () => {
  const client = new PGlite();
  await client.exec(`CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, completed BOOLEAN NOT NULL DEFAULT false, owner_email TEXT NOT NULL, created_at TEXT NOT NULL)`);
  const db = drizzle(client, { schema });
  database.get = () => db;
});

describe("private task actions", () => {
  it("rejects anonymous lists and writes", async () => {
    await expect(listTasks.run({})).rejects.toThrow();
    await expect(createTask.run({ title: "Private" })).rejects.toThrow();
    await expect(completeTask.run({ id: "4c43b41e-e00f-4f9b-ab12-ba9ca05b4cd3" })).rejects.toThrow();
  });
  it("validates titles and rejects client-provided ownership", async () => {
    const validate = createTask.schema["~standard"].validate;
    expect((await validate({ title: "   " })).issues).toBeDefined();
    expect((await validate({ title: "x".repeat(201) })).issues).toBeDefined();
    expect((await validate({ title: "Valid", ownerEmail: "other@example.test" })).issues).toBeDefined();
    expect((await validate({ title: " Valid " })).value).toEqual({ title: "Valid" });
  });
  it("authorizes navigation and resolves selected records without trusting context IDs", async () => {
    const task = await createTask.run({ title: "Selected" }, owner);
    await expect(navigate.run({ view: "tasks", id: task.id }, other)).rejects.toThrow();
    expect(state.has("navigate")).toBe(false);
    await navigate.run({ view: "tasks", id: task.id }, owner);
    expect(state.get("navigate")).toMatchObject({ view: "tasks", path: `/tasks?id=${task.id}` });
    state.set("navigation", { view: "tasks", taskId: task.id });
    state.set("selection", { kind: "task", id: task.id });
    expect(await viewScreen.run({}, owner)).toMatchObject({ openedTask: { id: task.id }, selection: { id: task.id } });
    await expect(viewScreen.run({}, other)).rejects.toThrow();
    await expect(navigate.run({ view: "tasks" })).rejects.toThrow();
    await expect(viewScreen.run({})).rejects.toThrow();
    state.set("navigation", { view: "home" });
    expect(await viewScreen.run({}, owner)).not.toHaveProperty("selection");
  });
  it("persists through UI and tool callers with owner-only access and idempotent completion", async () => {
    const task = await createTask.run({ title: "Review" }, owner);
    expect((await listTasks.run({}, owner)).map((row) => row.id)).toContain(task.id);
    expect(await listTasks.run({}, other)).toEqual([]);
    await expect(completeTask.run({ id: task.id }, other)).rejects.toThrow();
    expect((await completeTask.run({ id: task.id }, { ...owner, caller: "tool" })).completed).toBe(true);
    expect((await completeTask.run({ id: task.id }, owner)).completed).toBe(true);
    expect((await listTasks.run({}, owner)).find((row) => row.id === task.id)?.completed).toBe(true);
  });
});
